update pages set contenu = '{"gabarit":"fiche","chapeau":"Depuis septembre 2023, Migen gère le contrat de maintenance préventive annuelle des sites de Lyon pour VEEPEE, anciennement Vente Privée. Six techniciens polyvalents y sont en permanence.","fiche":[],"contexte":"**Plus un centre logistique grossit, plus le parc machine échappe au suivi.** Les pannes arrivent par une usure que personne n''a vu venir.\nLa problématique d''origine tenait en une phrase : des difficultés à assurer le maintien du parc machine sur un centre logistique volumineux.\n**Un parc étendu** : Plusieurs sites lyonnais à couvrir avec la même exigence.\n**Une usure non anticipée** : Les problèmes techniques dégénèrent en dysfonctionnements faute de préventif.\n**Des arrêts d''installation** : Au bout de la chaîne, ce sont des pertes de production.\n**Une bascule à réussir** : Changer de prestataire sans trou de couverture pendant la transition.","intervention":"**Une équipe résidente** : 6 techniciens polyvalents déployés en permanence sur site, capables de répondre à l''ensemble des besoins du centre logistique.\n**Un contrat annuel de préventif** : Migen assure la gestion du contrat de maintenance préventive annuelle des sites de Lyon.\n**Des opérations d''anticipation** : Le plan couvre les interventions qui préviennent les problèmes techniques et l''usure.\n**Une bascule bouclée en un mois** : La prise en charge de l''ensemble des sites a été réalisée en un mois.\n**Une continuité protégée** : La transition a été menée en limitant les pertes de production.","resultats":[]}'::jsonb where path = '/preuves/veepee-sites-lyon/';
update pages set contenu = jsonb_set(contenu, '{fiche}', (contenu->'fiche') || '[{"libelle":"Client","valeur":"VEEPEE, anciennement Vente Privée"},{"libelle":"Sites","valeur":"Sites de Lyon"},{"libelle":"Période","valeur":"Depuis septembre 2023, mission en cours"},{"libelle":"Effectif Migen","valeur":"6 techniciens polyvalents, en permanence sur site"},{"libelle":"Reprise du périmètre","valeur":"1 mois"},{"libelle":"Nature des travaux","valeur":"Maintenance préventive annuelle sous contrat"},{"libelle":"Problématique d''origine","valeur":"Maintien du parc machine d''un centre logistique volumineux"}]'::jsonb) where path = '/preuves/veepee-sites-lyon/';
update pages set contenu = jsonb_set(contenu, '{resultats}', (contenu->'resultats') || '[{"valeur":"Une reprise bouclée en un mois","libelle":"Le passage de l''ensemble des sites sous contrat Migen a tenu dans un mois."},{"valeur":"Une continuité protégée","libelle":"La bascule a limité les pertes de production."},{"valeur":"Un parc couvert en entier","libelle":"Les 6 techniciens polyvalents répondent à l''ensemble des besoins du centre logistique."}]'::jsonb) where path = '/preuves/veepee-sites-lyon/';
